//! Differential test: replays the stateful `TickBitmap` sequence generated from the Solidity
//! library and checks every result against the Rust port.
//!
//! Generated by: `cd diff-tests && forge test --match-test testGenerateTickBitmap`

use std::fs;
use std::path::PathBuf;

use windswap_engine::pool::tick_bitmap::{self, TickBitmap};
use windswap_engine::MathError;

enum Step {
    Reset(i32),
    Flip {
        tick: i32,
        ok: bool,
    },
    Next {
        tick: i32,
        lte: bool,
        next: i32,
        initialized: bool,
    },
}

fn steps() -> Vec<Step> {
    let path =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../diff-tests/vectors/tick_bitmap.txt");
    let text = fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    let steps: Vec<Step> = text
        .lines()
        .filter(|l| !l.is_empty())
        .map(|line| {
            let p: Vec<&str> = line.split('|').collect();
            match p.as_slice() {
                ["reset", spacing] => Step::Reset(spacing.parse().unwrap()),
                ["flip", tick, "ok"] => Step::Flip {
                    tick: tick.parse().unwrap(),
                    ok: true,
                },
                ["flip", tick, "err"] => Step::Flip {
                    tick: tick.parse().unwrap(),
                    ok: false,
                },
                ["next", tick, lte, "ok", next, initialized] => Step::Next {
                    tick: tick.parse().unwrap(),
                    lte: *lte == "1",
                    next: next.parse().unwrap(),
                    initialized: *initialized == "1",
                },
                _ => panic!("bad line: {line}"),
            }
        })
        .collect();
    assert!(!steps.is_empty(), "no vectors");
    steps
}

#[test]
fn tick_bitmap_matches_solidity() {
    let mut bitmap = TickBitmap::new();
    let mut spacing: Option<i32> = None;
    let (mut n_flip_ok, mut n_flip_err, mut n_init, mut n_uninit) = (0, 0, 0, 0);

    for step in steps() {
        match step {
            Step::Reset(s) => {
                bitmap = TickBitmap::new();
                spacing = Some(s);
            }
            Step::Flip { tick, ok } => {
                let s = spacing.expect("flip before reset");
                let before = bitmap.clone();
                let got = tick_bitmap::flip_tick(&mut bitmap, tick, s);
                if ok {
                    n_flip_ok += 1;
                    assert_eq!(got, Ok(()), "flip {tick} spacing {s} should succeed");
                } else {
                    n_flip_err += 1;
                    assert_eq!(
                        got,
                        Err(MathError::TickMisaligned),
                        "flip {tick} spacing {s} should revert"
                    );
                    assert_eq!(bitmap, before, "failed flip {tick} mutated the bitmap");
                }
            }
            Step::Next {
                tick,
                lte,
                next,
                initialized,
            } => {
                let s = spacing.expect("next before reset");
                let got = tick_bitmap::next_initialized_tick_within_one_word(&bitmap, tick, s, lte);
                assert_eq!(
                    got,
                    (next, initialized),
                    "next tick {tick} spacing {s} lte {lte}"
                );
                if initialized {
                    n_init += 1;
                } else {
                    n_uninit += 1;
                }
            }
        }
    }

    // The sequence must exercise both outcomes of every operation.
    assert!(
        n_init > 0 && n_uninit > 0,
        "next: init {n_init}, uninit {n_uninit}"
    );
    assert!(
        n_flip_ok > 0 && n_flip_err > 0,
        "flip: ok {n_flip_ok}, err {n_flip_err}"
    );
}
